TLM.f("Sancti/02-07",{"officium":"S. Romualdi Abbatis","rule":["vide C4c;","Gloria"],"ruleInherited":["Gloria"],"fallback":"Commune/C4c","from":{"Introitus":"Commune/C4c","Lectio":"Commune/C4c","Graduale":"Commune/C4c","GradualeP":"Commune/C4c","Tractus":"Commune/C4c","Evangelium":"Commune/C4c","Offertorium":"Commune/C4c","Communio":"Commune/C4c"},"sections":{"Introitus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 36:1"},{"k":"text","la":"Noli æmulári in malignántibus: neque zeláveris faciéntes iniquitátem."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium: lex Dei ejus in corde ipsíus. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Intercéssio nos, quǽsumus Dómine, beáti Romuáldi Abbátis comméndet: ut quod nostris méritis non valémus, ejus patrocínio assequámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 45:1-6"},{"k":"text","la":"Diléctus Deo et homínibus, cujus memória in benedictióne est. Símilem illum fecit in glória sanctórum, et magnificávit eum in timóre inimicórum, et in verbis suis monstra placávit. Glorificávit illum in conspéctu regum, et jussit illi coram pópulo suo, et osténdit illi glóriam suam. In fide et lenitáte ipsíus sanctum fecit illum, et elégit eum ex omni carne. Audívit enim eum et vocem ipsíus, et indúxit illum in nubem. Et dedit illi coram præcépta, et legem vitæ et disciplínæ."}],"Graduale":[{"k":"ref","la":"Ps 20:4-5"},{"k":"text","la":"Dómine, prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"text","la":"Vitam pétiit a te, et tribuísti ei longitúdinem diérum in sǽculum sǽculi. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 91:13"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur. Allelúja."},{"k":"ref","la":"Ps 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 20:4-5"},{"k":"text","la":"Dómine, prævenísti eum in benedictiónibus dulcédinis: posuísti in cápite ejus corónam de lápide pretióso."},{"k":"text","la":"Vitam pétiit a te, et tribuísti ei longitúdinem diérum in sǽculum sǽculi.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 19:27-29"},{"k":"text","la":"In illo témpore: Dixit Petrus ad Jesum: Ecce, nos relíquimus ómnia, et secúti sumus te: quid ergo erit nobis? Jesus autem dixit illis: Amen, dico vobis, quod vos, qui secúti estis me, in regeneratióne, cum séderit Fílius hóminis in sede majestátis suæ, sedébitis et vos super sedes duódecim, judicántes duódecim tribus Israël. Et omnis, qui relíquerit domum, vel fratres, aut soróres, aut patrem, aut matrem, aut uxórem, aut fílios, aut agros, propter nomen meum, céntuplum accípiet, et vitam ætérnam possidébit."}],"Offertorium":[{"k":"ref","la":"Ps 20:3-4"},{"k":"text","la":"Desidérium ánimæ ejus tribuísti ei, Dómine, et voluntáte labiórum ejus non fraudásti eum: posuísti in cápite ejus corónam de lápide pretióso. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sacris altáribus, Dómine, hóstias superpósitas sanctus Romuáldus Abbas, quaésumus, in salútem nobis proveníre depóscat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Prótegat nos, Dómine, cum tui perceptióne sacraménti beátus Romuáldus Abbas, pro nobis intercedéndo: ut et conversatiónis eius experiámur insígnia, et intercessiónis percipiámus suffrágia."},{"k":"macro","name":"Per Dominum"}]},"hr":{"52236fd7918c9b03":{"t":"Ps 36, 30-31, Ps 36, 1\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu. (Ps 36, 1) Ne zaviđaj sreći grešnika i ne žesti se radi zlotvora.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 36, 30-31) Pravednikova usta govore mudrost i jezik njegov kazuje pravdu. Zakon je Božji u srcu njegovu."},"436bcbea464c632f":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da nas zagovor blaženoga Romualda opata tebi preporuči, te njegovim zagovorom zadobijemo ono što nismo zavrijedili našim zaslugama.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"11efe36a44cd32d9":{"t":"Sir 45, 1-6\nČitanje knjige Mudrosti: Bogu je i ljudima drag, njegova je uspomena blagoslovljena. Gospodin mu je udijelio slavu kao svetima, i dao mu moć, da ga se boje neprijatelji. Na njegovu riječ prestaju strahote. Proslavio ga je pred vladarima, dao mu je zapovijedi pred narodom i pokazao mu svoju slavu. Posvetio ga je poradi njegove vjernosti i krotkosti, izabrao ga između svih ljudi. Čuo je njegov glas i uveo ga u oblak. On mu je sam dao zapovijedi, zakon života i mudrosti."},"6a5c7277f15ac135":{"t":"Ps 20, 4-5\nGospodine, pretekao si ga obilnim blagoslovima, na glavu si mu stavio krunu od dragog kamenja. U tebe je tražio život, i ti si mu dao dug život u vijeke vjekova.\n\nPs 111, 1-3\nBlago čovjeku koji se boji Gospodina i koji uživa u njegovim zapovijedima. Silno će biti na zemlji njegovo potomstvo, rod će pravednika biti blagoslovljen. U njegovu je domu slava i bogatstvo, i njegova pravednost ostaje u vijeke vjekova."},"9c583f5745d0c082":{"t":"Mt 19, 27-29\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Petar Isusu: Evo, mi smo ostavili sve i pošli za tobom. Što će, dakle, biti s nama? Isus im odgovori: Zaista vam kažem kad u vrijeme preporoda bude Sin čovječji sjedio na prijestolju svoga veličanstva, i vi koji ste pošli za mnom sjedit ćete na dvanaest prijestolja i suditi dvanaest Izraelskih plemena. A svaki koji radi mene ostavi kuću, ili braću, ili sestre, ili oca, ili majku, ili ženu, ili djecu ili polja, primit će stoput više i imat će vječni život."},"9c54648fe1a9c1c8":{"t":"Ps 20, 3 i 4\nTi si mu ispunio želju njegova srca i nisi mu uskratio molbe njegovih usana. Postavio si mu na glavu vijenac od dragog kamenja."},"f2fab9d6cab6ab96":{"t":"Molimo, Gospodine, da nam zagovorom svetoga Romualda opata ove žrtve koje su na svetom oltaru donesu spasenje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:"},"43352d99b4b928c1":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada."},"99c2559f9bad334a":{"t":"<i>Pomolimo se</i>.\nŠtitilo nas, Gospodine, primanje tvoje tajne zajedno sa zagovorom blaženog Romualda opata, da se i okoristimo divnim njegovim životom i osjetimo učinke njegova zagovora.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"25bb52de9a3b5b6e":{"t":"Ps 20, 4-5\nGospodine, pretekao si ga obilnim blagoslovima, na glavu si mu stavio krunu od dragog kamenja. U tebe je tražio život, i ti si mu dao dug život u vijeke vjekova.\n\nPs 91, 13\n<i>Aleluja</i>, <i>aleluja</i>.\nKao palma cvjeta i kao libanski cedar raste pravednik. <i>Aleluja</i>."}}});
